import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/evaluation.md","filePath":"03-developer/models/evaluation.md"}`),a={name:`03-developer/models/evaluation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to “Evaluation”">​</a></h1><p>Defines evaluation criteria for various entities in the system. Each evaluation specifies an aspect of an entity that can be rated; for example, criteria such as ergonomics, sound quality, and material quality can be defined for a pair of headphones.</p><p>User-submitted scores for each criterion are stored in the <code>Rate</code> model. Each criterion can be defined globally or assigned to a specific entity.</p><h2 id="evaluations-table" tabindex="-1"><code>evaluations</code> table <a class="header-anchor" href="#evaluations-table" aria-label="Permalink to “evaluations table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique evaluation criterion ID</td></tr><tr><td><code>title</code></td><td>TEXT</td><td>No</td><td>Evaluation criterion title, such as sound quality or material quality</td></tr><tr><td><code>evaluationable_type</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Type of entity to which the criterion is assigned; part of the polymorphic relationship</td></tr><tr><td><code>evaluationable_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the entity associated with the criterion; part of the polymorphic relationship</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Soft-deletion date</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation date</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Date of last update</td></tr></tbody></table><h2 id="properties-and-methods" tabindex="-1">Properties and methods <a class="header-anchor" href="#properties-and-methods" aria-label="Permalink to “Properties and methods”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>title</code> field supports storing and retrieving translations.</p><h2 id="relationship-with-the-rating-system" tabindex="-1">Relationship with the rating system <a class="header-anchor" href="#relationship-with-the-rating-system" aria-label="Permalink to “Relationship with the rating system”">​</a></h2><p>The <code>Rate</code> model is associated with this model through the <code>evaluation_id</code> field. Each <code>Rate</code> record stores a score for one criterion for a specific entity, submitted by one rater.</p><p>Criteria can be defined globally or assigned to a specific entity. When displaying a product&#39;s ratings, the criteria associated with it are retrieved through the product model&#39;s <code>evaluations()</code> method.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};